const API={
  get:async(path:string)=>{try{const r=await fetch(`/api/${path}`);return r.ok?r.json():null;}catch{return null;}},
  post:async(path:string,body:any)=>{try{const r=await fetch(`/api/${path}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});return r.ok?r.json():null;}catch{return null;}},
  patch:async(path:string,body:any)=>{try{const r=await fetch(`/api/${path}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});return r.ok?r.json():null;}catch{return null;}},
  del:async(path:string,id:number)=>{try{const r=await fetch(`/api/${path}`,{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify({id})});return r.ok?r.json():null;}catch{return null;}},
};

// ── EMAIL NOTIFICATION HELPER ─────────────────────────────────────────────────
const notify=async(subject:string,body:string,replyTo?:string)=>{
  try{
    const r=await fetch("/api/notify",{
      method:"POST",
      headers:{"Content-Type":"application/json"},
      body:JSON.stringify({subject,body,replyTo}),
    });
    const j=await r.json().catch(()=>null);
    if(!j?.success)console.error("Notify (admin) email failed:",j?.error||`HTTP ${r.status}`);
  }catch(e){console.error("Notify failed",e);}
};
const notifyAdmin=(subject:string,body:string,replyTo?:string)=>notify(subject,body,replyTo);
const notifyUser=async(to:string,subject:string,body:string)=>{
  try{
    const r=await fetch("/api/notify",{
      method:"POST",
      headers:{"Content-Type":"application/json"},
      body:JSON.stringify({subject,body,to,sendToUser:true}),
    });
    const j=await r.json().catch(()=>null);
    if(!j?.success)console.error("Notify (user) email failed:",j?.error||`HTTP ${r.status}`);
  }catch(e){console.error("NotifyUser failed",e);}
};

// ── FORM VALIDATION HELPERS ───────────────────────────────────────────────────
const isValidEmail=(email:string):boolean=>{
  const re=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return re.test(email.trim());
};
const isValidNGPhone=(phone:string):boolean=>{
  if(!phone||!phone.trim())return true; // phone often optional
  const cleaned=phone.replace(/[\s\-()]/g,"");
  // Nigerian formats: +234XXXXXXXXXX, 0XXXXXXXXXX, 234XXXXXXXXXX
  const re=/^(\+?234|0)[789][01]\d{8}$/;
  return re.test(cleaned);
};
const useFormValidation=()=>{
  const[errors,setErrors]=useState<Record<string,string>>({});
  const validate=(field:string,value:string,rules:{required?:boolean;email?:boolean;phone?:boolean;minLength?:number})=>{
    let error="";
    if(rules.required&&!value.trim())error="This field is required";
    else if(rules.email&&value&&!isValidEmail(value))error="Enter a valid email address";
    else if(rules.phone&&value&&!isValidNGPhone(value))error="Enter a valid phone number (e.g. 0801 234 5678)";
    else if(rules.minLength&&value.length<rules.minLength)error=`Must be at least ${rules.minLength} characters`;
    setErrors(e=>({...e,[field]:error}));
    return !error;
  };
  const clearError=(field:string)=>setErrors(e=>({...e,[field]:""}));
  return{errors,validate,clearError};
};

