const PBtn=({children,onClick,style={},sm=false,disabled=false}:any)=>(<button disabled={disabled} onClick={onClick} style={{background:disabled?"#94A3B8":`linear-gradient(135deg,${C.blueLt},${C.blue})`,color:"#fff",fontWeight:700,border:"none",borderRadius:6,cursor:disabled?"not-allowed":"pointer",padding:sm?"10px 20px":"14px 32px",fontSize:sm?13:15,boxShadow:disabled?"none":"0 4px 14px rgba(37,99,235,0.3)",transition:"all 0.2s",...style}}>{children}</button>);
