const SL=({children}:any)=>(<div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14}}><div style={{width:28,height:2,background:C.blueLt}}/><span style={{fontSize:11,fontWeight:700,color:C.blueLt,letterSpacing:"0.18em",textTransform:"uppercase" as const}}>{children}</span></div>);
const ST=({children,light=false,center=false}:any)=>(<h2 style={{fontSize:"clamp(1.7rem,3vw,2.6rem)",fontWeight:800,color:light?"#fff":C.dark,lineHeight:1.15,margin:0,textAlign:center?"center":"left",fontFamily:"'Playfair Display',Georgia,serif"}}>{children}</h2>);
const PH=({label,title,sub}:{label:string;title:any;sub:string})=>(<div style={{background:`linear-gradient(135deg,${C.navyDk} 0%,${C.navy} 60%,${C.blue} 100%)`,padding:"clamp(80px,10vw,100px) clamp(16px,4vw,32px) clamp(48px,7vw,70px)",textAlign:"center" as const,position:"relative" as const,overflow:"hidden"}}><div style={{position:"absolute" as const,inset:0,backgroundImage:`radial-gradient(ellipse at 50% 0%,rgba(37,99,235,0.15) 0%,transparent 65%)`}}/><div style={{position:"relative" as const}}><SL>{label}</SL><h1 style={{fontFamily:"'Playfair Display',Georgia,serif",fontSize:"clamp(2rem,4vw,3rem)",fontWeight:800,color:"#fff",margin:"12px 0 18px",lineHeight:1.15}}>{title}</h1><p style={{color:"rgba(255,255,255,0.6)",maxWidth:560,margin:"0 auto",fontSize:"clamp(14px,2vw,16px)",lineHeight:1.75}}>{sub}</p></div></div>);
const Bdg=({label,color=C.blueLt}:{label:string;color?:string})=>(<span style={{background:color,color:"#fff",fontSize:10,fontWeight:800,padding:"3px 9px",borderRadius:20,letterSpacing:"0.06em",textTransform:"uppercase" as const,whiteSpace:"nowrap" as const}}>{label}</span>);
const Card=({children,style={}}:any)=>(<div style={{background:"#fff",borderRadius:16,padding:"28px",border:`1px solid ${C.border}`,boxShadow:"0 2px 12px rgba(11,30,61,0.05)",...style}}>{children}</div>);
const Input=({label,value,onChange,onBlur,placeholder="",type="text",style={},error=""}:any)=>(<div style={{marginBottom:error?6:14}}>{label&&<label style={{fontSize:12,fontWeight:700,color:C.slate,display:"block",marginBottom:6}}>{label}</label>}<input type={type} value={value} onChange={onChange} onBlur={onBlur} placeholder={placeholder} style={{width:"100%",background:C.offWht,border:`1.5px solid ${error?C.danger:C.border}`,borderRadius:8,padding:"12px 14px",fontSize:14,color:C.dark,outline:"none",...style}}/>{error&&<div style={{color:C.danger,fontSize:11,fontWeight:600,marginTop:4,marginBottom:8}}>{error}</div>}</div>);
const Sel=({label,value,onChange,options}:any)=>(<div style={{marginBottom:14}}>{label&&<label style={{fontSize:12,fontWeight:700,color:C.slate,display:"block",marginBottom:6}}>{label}</label>}<select value={value} onChange={onChange} style={{width:"100%",background:C.offWht,border:`1.5px solid ${C.border}`,borderRadius:8,padding:"12px 14px",fontSize:14,color:C.dark,outline:"none",cursor:"pointer"}}>{options.map((o:any)=>(<option key={typeof o==="string"?o:o.value} value={typeof o==="string"?o:o.value}>{typeof o==="string"?o:o.label}</option>))}</select></div>);

const useReveal=()=>{const ref=useRef<HTMLDivElement>(null);const[visible,setVisible]=useState(false);useEffect(()=>{const el=ref.current;if(!el)return;const obs=new IntersectionObserver(([e])=>{if(e.isIntersecting){setVisible(true);obs.disconnect();}},{threshold:0.12});obs.observe(el);return()=>obs.disconnect();},[]);return{ref,visible};};
const Reveal=({children,delay=0,style={}}:any)=>{const{ref,visible}=useReveal();return(<div ref={ref} style={{opacity:visible?1:0,transform:visible?"translateY(0)":"translateY(28px)",transition:`opacity 0.65s ease ${delay}ms, transform 0.65s ease ${delay}ms`,...style}}>{children}</div>);};
const Counter=({target,suffix="",duration=1800}:{target:number;suffix?:string;duration?:number})=>{const[count,setCount]=useState(0);const{ref,visible}=useReveal();useEffect(()=>{if(!visible)return;let start=0;const step=target/(duration/16);const timer=setInterval(()=>{start+=step;if(start>=target){setCount(target);clearInterval(timer);}else setCount(Math.floor(start));},16);return()=>clearInterval(timer);},[visible,target,duration]);return<span ref={ref}>{count}{suffix}</span>;};

const LoadingScreen=({done}:{done:boolean})=>{
  const[visible,setVisible]=useState(false);const[mounted,setMounted]=useState(false);
  useEffect(()=>{setMounted(true);setVisible(true);},[]);
  useEffect(()=>{if(done&&mounted)setTimeout(()=>setVisible(false),600);},[done,mounted]);
  if(!mounted||!visible)return null;
  return(<div style={{position:"fixed" as const,inset:0,background:`linear-gradient(135deg,${C.navyDk},${C.navy})`,zIndex:99999,display:"flex",flexDirection:"column" as const,alignItems:"center",justifyContent:"center",transition:"opacity 0.6s ease",opacity:done?0:1,pointerEvents:done?"none":"all"}}>
    <div style={{perspective:"800px",marginBottom:24}}>
      <img src={NAV_LOGO} alt="JSP" style={{width:100,height:100,objectFit:"contain",display:"block",animation:"jspFlip 1.8s ease-in-out infinite",transformStyle:"preserve-3d" as any}}/>
    </div>
    <div style={{fontFamily:"'Playfair Display'",fontWeight:800,color:"#fff",fontSize:24,marginBottom:6,letterSpacing:"0.02em"}}>JustServicesPro</div>
    <div style={{color:C.slateL,fontSize:13,marginBottom:36,letterSpacing:"0.05em"}}>... connecting opportunities!</div>
    <div style={{width:220,height:3,background:"rgba(255,255,255,0.1)",borderRadius:2,overflow:"hidden"}}>
      <div style={{height:"100%",background:`linear-gradient(90deg,${C.blueLt},${C.steel})`,animation:"jspLoad 1.4s ease forwards",borderRadius:2}}/>
    </div>
    <style dangerouslySetInnerHTML={{__html:`@keyframes jspFlip{0%{transform:rotateY(0deg);}25%{transform:rotateY(90deg) scale(0.9);}50%{transform:rotateY(180deg);}75%{transform:rotateY(270deg) scale(0.9);}100%{transform:rotateY(360deg);}}@keyframes jspLoad{from{width:0}to{width:100%}}`}} />
  </div>);
};

const LiveTicker=({setPage}:{setPage:(p:Page)=>void})=>{const[mounted,setMounted]=useState(false);useEffect(()=>setMounted(true),[]);const items=[`🛡️ CAC Registered · RC: ${CAC_RC} · ${SUCCESS_RATE} Success Rate`,"🌐 Platforms: CertTrack · OrgNexus · DevTrac · ProDoc · Processa · WebMan · Appaholic · JustBuys · FixIt","📞 Free Consultation — Book Today","🚀 Websites from ₦80,000 · Apps from ₦350,000","📊 Active Grants Database Updated","🎓 JustServicesPro Academy — Enroll Now"];const[idx,setIdx]=useState(0);const[fade,setFade]=useState(true);useEffect(()=>{const t=setInterval(()=>{setFade(false);setTimeout(()=>{setIdx(i=>(i+1)%items.length);setFade(true);},400);},4000);return()=>clearInterval(t);},[]);if(!mounted)return null;return(<div className="ticker-bar" style={{background:`linear-gradient(90deg,${C.navyDk},${C.navy},${C.navyDk})`,borderBottom:`1px solid rgba(59,130,246,0.2)`,padding:"7px 24px",display:"flex",alignItems:"center",justifyContent:"center",gap:16,position:"fixed",top:0,left:0,right:0,zIndex:1001,height:38,boxSizing:"border-box" as const}}><div style={{width:8,height:8,borderRadius:"50%",background:C.success,animation:"wpulse2 2s infinite",flexShrink:0}}/><span style={{fontSize:12,color:"rgba(255,255,255,0.8)",fontWeight:500,opacity:fade?1:0,transition:"opacity 0.4s",textAlign:"center" as const}}>{items[idx]}</span><button onClick={()=>setPage("Contact")} className="ticker-cta" style={{background:`linear-gradient(135deg,${C.blueLt},${C.blue})`,border:"none",borderRadius:6,padding:"4px 12px",color:"#fff",fontSize:11,fontWeight:700,cursor:"pointer",flexShrink:0,whiteSpace:"nowrap" as const}}>Get Started</button><style dangerouslySetInnerHTML={{__html:`@keyframes wpulse2{0%,100%{box-shadow:0 0 0 0 rgba(16,185,129,0.6)}70%{box-shadow:0 0 0 7px rgba(16,185,129,0)}}.wfab{animation:wfab2 2.5s infinite;}@keyframes wfab2{0%,100%{box-shadow:0 0 0 0 rgba(37,211,102,0.5)}70%{box-shadow:0 0 0 12px rgba(37,211,102,0)}}`}} /></div>);};

