const NavDrop=({label,active,items,go,page}:{label:string;active:boolean;items:{label:string;page:Page;sub?:string;href?:string}[];go:(p:Page)=>void;page:Page})=>{
  const[open,setOpen]=useState(false);const ref=useRef<HTMLDivElement>(null);
  useEffect(()=>{const fn=(e:MouseEvent)=>{if(ref.current&&!ref.current.contains(e.target as Node))setOpen(false);};document.addEventListener("mousedown",fn);return()=>document.removeEventListener("mousedown",fn);},[]);
  return(<div ref={ref} style={{position:"relative" as const}}><button onClick={()=>setOpen(o=>!o)} style={{background:active?"rgba(59,130,246,0.12)":"transparent",border:"none",color:active?C.steel:"rgba(255,255,255,0.75)",fontSize:13.5,fontWeight:500,padding:"6px 13px",borderRadius:4,cursor:"pointer",display:"flex",alignItems:"center",gap:4}}>{label}<Icon n="chevronDown" s={13}/></button>{open&&(<div style={{position:"absolute" as const,top:"calc(100% + 8px)",left:0,maxWidth:"calc(100vw - 32px)",background:"#fff",borderRadius:12,boxShadow:"0 8px 32px rgba(11,30,61,0.18)",border:`1px solid ${C.border}`,padding:6,minWidth:210,zIndex:1000}}>{items.map(item=>item.href?(<a key={item.page} href={item.href} onClick={()=>setOpen(false)} style={{width:"100%",display:"flex",flexDirection:"column" as const,alignItems:"flex-start",padding:"10px 14px",borderRadius:8,border:"none",background:page===item.page?C.accent:"transparent",cursor:"pointer",textAlign:"left" as const,textDecoration:"none"}}><span style={{fontSize:13,fontWeight:700,color:page===item.page?C.blueLt:C.dark}}>{item.label}</span>{item.sub&&<span style={{fontSize:11,color:C.slateL,marginTop:2}}>{item.sub}</span>}</a>):(<button key={item.page} onClick={()=>{go(item.page);setOpen(false);}} style={{width:"100%",display:"flex",flexDirection:"column" as const,alignItems:"flex-start",padding:"10px 14px",borderRadius:8,border:"none",background:page===item.page?C.accent:"transparent",cursor:"pointer",textAlign:"left" as const}}><span style={{fontSize:13,fontWeight:700,color:page===item.page?C.blueLt:C.dark}}>{item.label}</span>{item.sub&&<span style={{fontSize:11,color:C.slateL,marginTop:2}}>{item.sub}</span>}</button>))}</div>)}</div>);
};

