  const share=(p:string)=>{const u=encodeURIComponent(url||(typeof window!=="undefined"?window.location.href:""));const t=encodeURIComponent(title);const m:Record<string,string>={twitter:`https://twitter.com/intent/tweet?text=${t}&url=${u}`,facebook:`https://www.facebook.com/sharer/sharer.php?u=${u}`,linkedin:`https://www.linkedin.com/shareArticle?mini=true&url=${u}&title=${t}`,whatsapp:`https://wa.me/?text=${t}%20${u}`};window.open(m[p],"_blank");setOpen(false);};
