const Typewriter=({words,speed=90,pause=1800}:{words:string[];speed?:number;pause?:number})=>{
  const[wIdx,setWIdx]=useState(0);const[text,setText]=useState("");const[deleting,setDeleting]=useState(false);
  useEffect(()=>{
    const current=words[wIdx];
    const t=setTimeout(()=>{
      if(!deleting){
        if(text.length<current.length)setText(current.slice(0,text.length+1));
        else setTimeout(()=>setDeleting(true),pause);
      }else{
        if(text.length>0)setText(current.slice(0,text.length-1));
        else{setDeleting(false);setWIdx(i=>(i+1)%words.length);}
      }
    },deleting?speed/2:speed);
    return()=>clearTimeout(t);
  },[text,deleting,wIdx,words,speed,pause]);
  return(<span style={{background:"linear-gradient(135deg,#3B82F6,#93C5FD)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>{text}<span className="tw-cursor" style={{WebkitTextFillColor:"#93C5FD",color:"#93C5FD"}}>|</span></span>);
};

