// ── ROOT APP ──────────────────────────────────────────────────────────────────

// ── COOKIE / NDPR CONSENT BANNER ──────────────────────────────────────────────
const CookieConsent=({setPage}:{setPage:(p:Page)=>void})=>{
  const[visible,setVisible]=useState(false);
  const[detailsOpen,setDetailsOpen]=useState(false);
  useEffect(()=>{
    try{
      const consent=localStorage.getItem("jsp_cookie_consent");
      if(!consent)setVisible(true);
    }catch(e){setVisible(true);}
  },[]);
  const accept=()=>{try{localStorage.setItem("jsp_cookie_consent","accepted");}catch(e){}setVisible(false);};
  const reject=()=>{try{localStorage.setItem("jsp_cookie_consent","rejected");}catch(e){}setVisible(false);};
  if(!visible)return null;
  return(<div style={{position:"fixed" as const,bottom:0,left:0,right:0,zIndex:99998,background:C.navyDk,borderTop:"1px solid rgba(59,130,246,0.25)",padding:"18px 24px",boxShadow:"0 -8px 30px rgba(0,0,0,0.3)"}}>
    <div className="cookie-banner" style={{maxWidth:1100,margin:"0 auto",display:"flex",alignItems:"center",gap:20,flexWrap:"wrap" as const}}>
      <div style={{flex:1,minWidth:260}}>
        <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}><span style={{color:C.steel}}><Icon n="shield" s={16}/></span><span style={{fontFamily:"'Playfair Display'",fontWeight:700,color:"#fff",fontSize:14}}>We value your privacy</span></div>
        <p style={{color:"rgba(255,255,255,0.55)",fontSize:12,lineHeight:1.6,margin:0}}>
          We use cookies to improve your experience, analyze site traffic, and personalize content, in line with the Nigeria Data Protection Act.
          {!detailsOpen&&<button onClick={()=>setDetailsOpen(true)} style={{background:"none",border:"none",color:C.steel,cursor:"pointer",fontSize:12,fontWeight:600,marginLeft:6,padding:0,textDecoration:"underline"}}>Learn more</button>}
        </p>
        {detailsOpen&&(<p style={{color:"rgba(255,255,255,0.45)",fontSize:11,lineHeight:1.6,marginTop:8}}>
          Essential cookies are required for the site to function. Analytics cookies help us understand usage patterns. You can read our full{" "}
          <a href="/privacy" style={{color:C.steel,cursor:"pointer",textDecoration:"underline"}}>Privacy Policy</a> for details on how we handle your data.
        </p>)}
      </div>
      <div className="cookie-btns" style={{display:"flex",gap:10,flexShrink:0}}>
        <button onClick={reject} style={{background:"rgba(255,255,255,0.06)",border:"1px solid rgba(255,255,255,0.15)",borderRadius:8,padding:"10px 18px",color:"rgba(255,255,255,0.7)",fontSize:13,fontWeight:600,cursor:"pointer"}}>Reject</button>
        <button onClick={accept} style={{background:`linear-gradient(135deg,${C.blueLt},${C.blue})`,border:"none",borderRadius:8,padding:"10px 20px",color:"#fff",fontSize:13,fontWeight:700,cursor:"pointer"}}>Accept All</button>
      </div>
    </div>
  </div>);
};

// ── PAYMENT RESULT BANNER (shown after redirect back from Flutterwave) ──────
const PaymentResultBanner=({result,onClose}:{result:"success"|"cancelled"|"failed";onClose:()=>void})=>{
  const cfg={
    success:{icon:"checkCircle",color:C.success,title:"Payment Successful!",msg:"Thank you! We've received your payment and will reach out within 2 hours to get started."},
    cancelled:{icon:"x",color:C.slate,title:"Payment Cancelled",msg:"You cancelled the checkout. No charge was made — feel free to try again whenever you're ready."},
    failed:{icon:"x",color:"#DC2626",title:"Payment Failed",msg:"Something went wrong and we couldn't confirm this payment. If you were charged, please contact us with your reference and we'll sort it out right away."},
  }[result];
  return(<div style={{position:"fixed" as const,inset:0,background:"rgba(0,0,0,0.6)",zIndex:99999,display:"flex",alignItems:"center",justifyContent:"center",padding:20}} onClick={e=>{if(e.target===e.currentTarget)onClose();}}>
    <div style={{background:"#fff",borderRadius:20,padding:"36px 32px",width:"100%",maxWidth:420,textAlign:"center" as const,boxShadow:"0 24px 80px rgba(0,0,0,0.25)"}}>
      <div style={{width:64,height:64,background:`${cfg.color}18`,borderRadius:"50%",display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 20px"}}>
        <span style={{color:cfg.color}}><Icon n={cfg.icon} s={32}/></span>
      </div>
      <h3 style={{fontFamily:"'Playfair Display'",fontWeight:800,color:C.dark,fontSize:20,marginBottom:10}}>{cfg.title}</h3>
      <p style={{color:C.slate,fontSize:14,lineHeight:1.7,marginBottom:24}}>{cfg.msg}</p>
      <PBtn onClick={onClose} style={{width:"100%"}}>Continue</PBtn>
      {result==="failed"&&<a href={WHATSAPP} target="_blank" rel="noreferrer" style={{display:"block",marginTop:12,color:C.blueLt,fontSize:13,fontWeight:600,textDecoration:"none"}}>Contact us on WhatsApp</a>}
    </div>
  </div>);
};

export default function App(){
  const[page,setPage]=useState<Page>("Home");
  const[posts,setPosts]=useState<BlogPost[]>(INIT_POSTS);
  const[projects,setProjects]=useState<Project[]>(INIT_PROJECTS);
  const[products,setProducts]=useState<ShopProduct[]>(INIT_SHOP_PRODUCTS);
  const[grants,setGrants]=useState<Grant[]>(INIT_GRANTS);
  const[cases,setCases]=useState<CaseStudy[]>(INIT_CASE_STUDIES);
  const[bookings,setBookings]=useState<Booking[]>([]);
  const[clients,setClients]=useState<Client[]>([DEMO_CLIENT]);
  const[courses,setCourses]=useState<Course[]>(INIT_COURSES);
  const[students,setStudents]=useState<Student[]>(INIT_STUDENTS);
  const[payment,setPayment]=useState<{amount:number;title:string}|null>(null);
  const[paymentResult,setPaymentResult]=useState<"success"|"cancelled"|"failed"|null>(null);
  const[loaded,setLoaded]=useState(false);
  const[enrollCourse,setEnrollCourse]=useState<Course|null>(null);
  const isAdmin=page==="Admin";
  const go=(p:Page)=>{setPage(p);if(typeof window!=="undefined"){window.scrollTo({top:0,behavior:"smooth"});try{window.history.pushState(null,"","#"+p.toLowerCase());}catch(e){}initOGTags();}};
  useEffect(()=>{
    const t=setTimeout(()=>setLoaded(true),1800);
    initOGTags();
    try{
      const hash=window.location.hash.replace("#","").toLowerCase();
      const pm:Record<string,Page>={home:"Home",about:"About",services:"Services",products:"Products",courses:"Courses",shop:"Shop",blog:"Blog",faqs:"FAQs",contact:"Contact",calculator:"Calculator",grants:"Grants",casestudies:"CaseStudies",portal:"Portal",studentportal:"StudentPortal",admin:"Admin",privacy:"Privacy",terms:"Terms",refund:"Refund"};
      if(hash==="privacy"){window.location.replace("/privacy");return;}
      if(hash==="services"){window.location.replace("/services");return;}
      if(hash==="products"){window.location.replace("/products");return;}
      if(hash==="terms"){window.location.replace("/terms");return;}
      if(hash==="refund"){window.location.replace("/refund");return;}
      if(hash==="faqs"){window.location.replace("/faqs");return;}
      if(hash==="about"){window.location.replace("/about");return;}
      if(hash==="blog"){window.location.replace("/blog");return;}
      if(hash==="casestudies"){window.location.replace("/case-studies");return;}
      if(hash==="grants"){window.location.replace("/grants");return;}
      if(hash==="calculator"){window.location.replace("/calculator");return;}
      if(hash==="contact"){window.location.replace("/contact");return;}
      if(hash==="payment-success"||hash==="payment-cancelled"||hash==="payment-failed"){
        setPaymentResult(hash.replace("payment-","") as "success"|"cancelled"|"failed");
        try{window.history.replaceState(null,"","/");}catch(e){}
      }else if(hash&&pm[hash])setPage(pm[hash]);
    }catch(e){}

    (async()=>{
      await API.get("init").catch(()=>{});
      // Load every dataset from the DB. If a table is still empty (first
      // deploy after adding persistence), seed it from the original hardcoded
      // data so the public site keeps showing the same content it always has
      // — the admin dashboard then manages the real DB rows going forward.
      const [dbPosts,dbProjects,dbProducts,dbGrants,dbCases,dbCourses,dbStudents,dbClients,dbBookings]=await Promise.all([
        API.get("posts"),API.get("projects"),API.get("products"),API.get("grants"),
        API.get("cases"),API.get("courses"),API.get("students"),API.get("clients"),API.get("bookings"),
      ]);
      const needsSeed=!dbPosts?.length||!dbProjects?.length||!dbProducts?.length||!dbGrants?.length||!dbCases?.length||!dbCourses?.length;
      if(needsSeed){
        await API.post("seed",{posts:INIT_POSTS,projects:INIT_PROJECTS,products:INIT_SHOP_PRODUCTS,grants:INIT_GRANTS,cases:INIT_CASE_STUDIES,courses:INIT_COURSES}).catch(()=>{});
      }
      setPosts(dbPosts?.length?dbPosts:INIT_POSTS);
      setProjects(dbProjects?.length?dbProjects:INIT_PROJECTS);
      setProducts(dbProducts?.length?dbProducts:INIT_SHOP_PRODUCTS);
      setGrants(dbGrants?.length?dbGrants:INIT_GRANTS);
      setCases(dbCases?.length?dbCases:INIT_CASE_STUDIES);
      setCourses(dbCourses?.length?dbCourses:INIT_COURSES);
      if(dbStudents?.length)setStudents(dbStudents);
      if(dbClients?.length)setClients(dbClients);
      if(dbBookings)setBookings(dbBookings);
    })();

    return()=>clearTimeout(t);
  },[]);
  return(<div style={{minHeight:"100vh"}} suppressHydrationWarning>
    <LoadingScreen done={loaded}/>
    {loaded&&!isAdmin&&<LiveTicker setPage={go}/>}
    {!isAdmin&&<Navbar page={page} setPage={go}/>}
    {loaded&&!isAdmin&&<CookieConsent setPage={go}/>}
    {paymentResult&&<PaymentResultBanner result={paymentResult} onClose={()=>setPaymentResult(null)}/>}
    <div>
      {page==="Home"         &&<HomePage setPage={go} posts={posts} projects={projects} cases={cases}/>}
      {page==="About"        &&<AboutPage projects={projects} setPage={go}/>}
      {page==="Services"     &&<ServicesPage setPage={go} setPayment={setPayment}/>}
      {page==="Products"     &&<ProductsPage setPage={go}/>}
      {page==="Shop"         &&<ShopPage products={products} setPayment={setPayment} setPage={go}/>}
      {page==="Courses"      &&<CoursesPage courses={courses} setPage={go} setPayment={setPayment} setEnrollCourse={setEnrollCourse}/>}
      {page==="StudentPortal"&&<StudentPortalPage students={students} courses={courses} setPayment={setPayment}/>}
      {page==="Blog"         &&<BlogPage posts={posts}/>}
      {page==="FAQs"         &&<FAQsPage/>}
      {page==="Contact"      &&<ContactPage bookings={bookings} setBookings={setBookings}/>}
      {page==="Calculator"   &&<CalculatorPage setPayment={setPayment}/>}
      {page==="Grants"       &&<GrantsPage grants={grants} setPage={go}/>}
      {page==="CaseStudies"  &&<CaseStudiesPage cases={cases} setPage={go}/>}
      {page==="Portal"       &&<PortalPage clients={clients} setClients={setClients}/>}
      {page==="Admin"        &&<AdminPage posts={posts} setPosts={setPosts} projects={projects} setProjects={setProjects} products={products} setProducts={setProducts} grants={grants} setGrants={setGrants} cases={cases} setCases={setCases} bookings={bookings} setBookings={setBookings} clients={clients} setClients={setClients} courses={courses} setCourses={setCourses} students={students} setStudents={setStudents} onLogout={()=>go("Home")}/>}
      {page==="Privacy"      &&<PrivacyPage/>}
      {page==="Terms"        &&<TermsPage/>}
      {page==="Refund"       &&<RefundPage/>}
    </div>
    {!isAdmin&&<Footer setPage={go}/>}
    {!isAdmin&&loaded&&<ChatWidget/>}
    {!isAdmin&&(<a href={WHATSAPP} target="_blank" rel="noreferrer" aria-label="Chat with us on WhatsApp" className="wa-btn wfab" style={{position:"fixed",bottom:28,right:28,zIndex:9997,width:52,height:52,background:"#25D366",borderRadius:"50%",display:"flex",alignItems:"center",justifyContent:"center",textDecoration:"none",boxShadow:"0 4px 20px rgba(37,211,102,0.5)"}}><span style={{color:"#fff"}}><Icon n="whatsapp" s={26}/></span></a>)}
    {enrollCourse&&<EnrollModal course={enrollCourse} onClose={()=>setEnrollCourse(null)} onSuccess={(s)=>setStudents(p=>[...p,s])} setPayment={setPayment}/>}
    {payment&&<PaymentModal amount={payment.amount} title={payment.title} onClose={()=>setPayment(null)} onSuccess={()=>{setTimeout(()=>setPayment(null),3500);}} depositMode={true}/>}
    {!isAdmin&&(<div style={{position:"fixed",bottom:28,left:28,zIndex:9995}}><button onClick={()=>go("Admin")} style={{background:"rgba(7,20,40,0.88)",border:"1px solid rgba(59,130,246,0.2)",borderRadius:9,padding:"8px 13px",color:"rgba(255,255,255,0.45)",fontSize:11,cursor:"pointer",fontWeight:600,backdropFilter:"blur(8px)",display:"flex",alignItems:"center",gap:5}}><Icon n="lock" s={11}/> Admin</button></div>)}
  </div>);
}
